/**
 * Errors returned by alias lifecycle operations.
 */
public enum AliasError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Client settings or an operation request is invalid.
     */
    case InvalidRequest(message: String)
    
    /**
     * The provider API base URL is invalid.
     */
    case InvalidBaseUrl(message: String)
    
    /**
     * The authentication token cannot be represented as an HTTP header.
     */
    case InvalidAuthenticationToken(message: String)
    
    /**
     * The supplied connection identity is not a canonical UUID v4.
     */
    case InvalidConnectionIdentity(message: String)
    
    /**
     * The provider attempted an authenticated redirect. Redirect locations are deliberately not
     * rendered because they can contain sensitive data.
     */
    case RedirectRejected(message: String)
    
    /**
     * The provider rejected authentication.
     */
    case AuthenticationFailed(message: String)
    
    /**
     * The provider rate limit was reached.
     */
    case RateLimited(message: String)
    
    /**
     * The provider returned an unsuccessful response.
     *
     * Provider-controlled response text is deliberately omitted because it can reflect API keys,
     * alias inputs, or terminal control sequences into application logs.
     */
    case Provider(message: String)
    
    /**
     * A lifecycle mutation was dispatched, but a transport failure made its final state unknown.
     * Callers must reconcile state instead of blindly replaying the operation.
     */
    case MutationOutcomeUnknown(message: String)
    
    /**
     * The provider confirmed a mutation, but the SDK could not refresh the resulting resource.
     * Replaying the mutation is unsafe; callers should retry only the corresponding read.
     */
    case MutationCommittedButRefreshFailed(message: String)
    
    /**
     * The provider returned success for a mutation, but its response could not be validated.
     * The operation may have committed and must be reconciled instead of replayed.
     */
    case MutationResponseInvalid(message: String)
    
    /**
     * Concurrent actors prevented a toggle-only API from converging on the requested state.
     */
    case ConcurrentMutation(message: String)
    
    /**
     * A provider response exceeded the SDK limit.
     */
    case ResponseTooLarge(message: String)
    
    /**
     * A successful provider response was not JSON.
     */
    case UnexpectedContentType(message: String)
    
    /**
     * A successful provider response did not match the SimpleLogin API contract.
     */
    case InvalidResponse(message: String)
    
    /**
     * A provider response was valid JSON but reported an impossible lifecycle result.
     */
    case InvalidResponseValue(message: String)
    
    /**
     * The HTTP request failed. URLs are removed before this error is retained or rendered.
     */
    case Transport(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AliasError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAliasError: FfiConverterRustBuffer {
    typealias SwiftType = AliasError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AliasError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidRequest(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .InvalidBaseUrl(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .InvalidAuthenticationToken(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .InvalidConnectionIdentity(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .RedirectRejected(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .AuthenticationFailed(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .RateLimited(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .Provider(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .MutationOutcomeUnknown(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .MutationCommittedButRefreshFailed(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 11: return .MutationResponseInvalid(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 12: return .ConcurrentMutation(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 13: return .ResponseTooLarge(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 14: return .UnexpectedContentType(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 15: return .InvalidResponse(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 16: return .InvalidResponseValue(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 17: return .Transport(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AliasError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .InvalidRequest(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .InvalidBaseUrl(_ /* message is ignored*/):
